def acquire(api, arm, request, approach_xyz, open_width_m):
    grasp = api.compile_pose("grasp", request)
    if grasp.get("status") != "ok":
        return grasp
    q = grasp["orientation_xyzw"]
    for command in (
        lambda: api.gripper_goto(arm, open_width_m),
        lambda: api.goto_pose(arm, approach_xyz, q),
        lambda: api.goto_pose(arm, grasp["target_position_xyz"], q),
        lambda: api.gripper_goto(arm, 0.0),
    ):
        result = command()
        if result.get("status") != "ok":
            return result
    return api.get_wrist_view(arm)

