def inspect_region(api, image_path, box, depth_path, intrinsics_path):
    mask = api.get_sam_mask_from_box(image_path, box)
    if mask.get("status") != "ok":
        return mask
    return api.measure_visible_geometry(
        mask["mask_path"], depth_path, intrinsics_path)

def place(api, arm, request, open_width_m):
    previous = api.get_previous_proposer_state()
    if not previous.get("held_object_state"):
        return previous
    request["held_object_state"] = previous["held_object_state"]
    request["table_z_world"] = previous["table_z_world"]
    compiled = api.compile_pose("place", request)
    if compiled.get("status") != "ok":
        return compiled
    for key in ("carry_tool0_pose", "release_tool0_pose"):
        pose = compiled[key]
        moved = api.goto_pose(arm, pose["target_position_xyz"], pose["orientation_xyzw"])
        if moved.get("status") != "ok":
            return moved
    opened = api.gripper_goto(arm, open_width_m)
    if opened.get("status") != "ok":
        return opened
    return api.get_scene_image()

def contact_step(api, arm, position_xyz, orientation_xyzw):
    before = api.get_scene_image()
    result = api.goto_pose(arm, position_xyz, orientation_xyzw)
    after = api.get_scene_image()
    return {"before": before, "motion": result, "after": after}

